// tb/v3/tb_ch06_hanning.v
// Cycle-accurate, bit-exact testbench for rtl/v3/ch06_hanning_window.v
// Compatible with iverilog -g2012 -Wall
//
// Verification protocol:
// - Reads 3250 cycle vectors generated by Python twin (verify_v3/ch06_window_twin.py)
// - Covers Clean Frame, Noisy Frame (SNR 5dB), Stress Frame A (max |xw| = 59379),
//   Stress Frame B (alternating square), and Silence Frame
// - Testbench sampling convention:
//     * Inputs driven at @(negedge clk)
//     * Registered outputs checked at @(posedge clk); #1
// - Does not abort on mismatch; counts all comparison errors and reports total

`timescale 1ns/1ps

module tb_ch06_hanning;

    localparam integer DATA_W          = 17;
    localparam integer ROM_W           = 16;
    localparam integer PROD_W          = 34;
    localparam integer N_SAMPLES       = 638;
    localparam integer LP_FIRST        = 212;
    localparam integer LP_LAST         = 425;
    localparam integer EXPECTED_CYCLES = 3250;

    // Clock generation (50 MHz, 20 ns period)
    reg clk = 0;
    always #10 clk = ~clk;

    // DUT signals
    reg                     rst_n;
    reg                     start;
    wire                    busy;
    reg                     in_valid;
    reg  signed [DATA_W-1:0] in_d;

    wire                    out_valid;
    wire signed [DATA_W-1:0] out_xw;
    wire                    out_done;
    wire        [15:0]      out_lp;

    // Instantiate DUT
    ch06_hanning_window #(
        .DATA_W    (DATA_W),
        .ROM_W     (ROM_W),
        .PROD_W    (PROD_W),
        .N_SAMPLES (N_SAMPLES),
        .LP_FIRST  (LP_FIRST),
        .LP_LAST   (LP_LAST),
        .INIT_FILE ("golden_v2/rom/hanning638_q15.hex")
    ) dut (
        .clk       (clk),
        .rst_n     (rst_n),
        .start     (start),
        .busy      (busy),
        .in_valid  (in_valid),
        .in_d      (in_d),
        .out_valid (out_valid),
        .out_xw    (out_xw),
        .out_done  (out_done),
        .out_lp    (out_lp)
    );

    // Testbench tracking variables
    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus record variables
    integer stim_rst_n;
    integer stim_start;
    integer stim_in_vld;
    integer stim_in_d;

    // Expected record variables
    integer exp_out_vld;
    integer exp_out_xw;
    integer exp_out_done;
    integer exp_out_lp;

    initial begin
        rst_n     = 0;
        start     = 0;
        in_valid  = 0;
        in_d      = {DATA_W{1'b0}};
        cycle_idx = 0;
        errors    = 0;

        // Open stimulus file (try verify_v3 path then relative path)
        stim_fd = $fopen("verify_v3/tb_ch06_hanning_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch06_hanning_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch06_hanning_stim.txt");
            $finish;
        end

        // Open expected file (try verify_v3 path then relative path)
        exp_fd = $fopen("verify_v3/tb_ch06_hanning_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch06_hanning_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch06_hanning_expected.txt");
            $finish;
        end

        $display("=== STARTING CH06 HANNING WINDOW CYCLE-BY-CYCLE VERIFICATION ===");

        // Align to falling edge
        @(negedge clk);

        while ($fscanf(stim_fd, "%d %d %d %d\n",
                       stim_rst_n, stim_start, stim_in_vld, stim_in_d) == 4 &&
               $fscanf(exp_fd, "%d %d %d %d\n",
                       exp_out_vld, exp_out_xw, exp_out_done, exp_out_lp) == 4) begin

            // 1. Drive inputs during clock low phase
            rst_n    = (stim_rst_n != 0) ? 1'b1 : 1'b0;
            start    = (stim_start != 0) ? 1'b1 : 1'b0;
            in_valid = (stim_in_vld != 0) ? 1'b1 : 1'b0;
            in_d     = stim_in_d[DATA_W-1:0];

            // 2. Wait for clock rising edge and sample registered outputs after #1
            @(posedge clk);
            #1;

            // Check out_valid
            if (out_valid !== ((exp_out_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: out_valid mismatch DUT=%b EXP=%b",
                         cycle_idx, out_valid, exp_out_vld != 0);
                errors = errors + 1;
            end

            // Check out_xw when out_valid is active
            if (out_valid && (out_xw !== exp_out_xw[DATA_W-1:0])) begin
                $display("[FAIL] Cycle %0d: out_xw mismatch DUT=%0d EXP=%0d",
                         cycle_idx, $signed(out_xw), exp_out_xw);
                errors = errors + 1;
            end

            // Check out_done
            if (out_done !== ((exp_out_done != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: out_done mismatch DUT=%b EXP=%b",
                         cycle_idx, out_done, exp_out_done != 0);
                errors = errors + 1;
            end

            // Check out_lp when out_done is asserted
            if (out_done && (out_lp !== exp_out_lp[15:0])) begin
                $display("[FAIL] Cycle %0d: out_lp mismatch DUT=%0d EXP=%0d",
                         cycle_idx, out_lp, exp_out_lp);
                errors = errors + 1;
            end

            cycle_idx = cycle_idx + 1;
            @(negedge clk);
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        $display("-------------------------------------------------------");
        $display("Simulation finished. Total cycles tested: %0d", cycle_idx);

        if (cycle_idx != EXPECTED_CYCLES) begin
            $display("[FAIL] Total cycles read (%0d) does not match EXPECTED_CYCLES (%0d)!",
                     cycle_idx, EXPECTED_CYCLES);
            errors = errors + 1;
        end

        $display("Total comparison errors: %0d", errors);

        if (errors == 0) begin
            $display("=== ALL %0d VECTORS MATCHED SUCCESSFULLY ===", cycle_idx);
        end else begin
            $display("[FAIL] Verification finished with %0d errors!", errors);
        end
        $display("-------------------------------------------------------");
        $finish;
    end

endmodule
